CREATE TABLE IF NOT EXISTS roles (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(40) NOT NULL UNIQUE,permissions_json JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users (id VARCHAR(64) PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role_id INT NOT NULL,bureau_id INT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS institutions (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,code VARCHAR(40) UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bureaus (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS complaints (id BIGINT PRIMARY KEY,reference_id VARCHAR(40) NOT NULL UNIQUE,institution_id BIGINT NULL,institution_name VARCHAR(180) NOT NULL,aicte_id VARCHAR(40),category VARCHAR(80) NOT NULL,subject VARCHAR(160) NOT NULL,description TEXT NOT NULL,complainant_name VARCHAR(100),complainant_email VARCHAR(190),complainant_phone VARCHAR(30),status ENUM('Pending','In Progress','Resolved','Escalated') NOT NULL DEFAULT 'Pending',bureau VARCHAR(100) NOT NULL,due_at DATETIME NOT NULL,tracking_hash CHAR(64),synthetic BOOLEAN NOT NULL DEFAULT FALSE,assigned_to VARCHAR(64),created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_complaints_status(status),INDEX idx_complaints_bureau(bureau),INDEX idx_complaints_due(due_at),INDEX idx_complaints_inst(institution_id),CONSTRAINT fk_complaint_institution FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS complaint_assignments (id BIGINT AUTO_INCREMENT PRIMARY KEY,complaint_id BIGINT NOT NULL,bureau_id INT NOT NULL,user_id VARCHAR(64),assigned_by VARCHAR(64),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE,FOREIGN KEY(bureau_id) REFERENCES bureaus(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS complaint_status_history (id BIGINT AUTO_INCREMENT PRIMARY KEY,complaint_id BIGINT NOT NULL,status VARCHAR(120) NOT NULL,actor_user_id VARCHAR(64),is_public BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_history_case(complaint_id,created_at),FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS public_updates (id CHAR(36) PRIMARY KEY,complaint_id BIGINT NOT NULL,user_id VARCHAR(64),message VARCHAR(1000) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS internal_notes (id CHAR(36) PRIMARY KEY,complaint_id BIGINT NOT NULL,user_id VARCHAR(64) NOT NULL,note TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS complaint_documents (id CHAR(36) PRIMARY KEY,complaint_id BIGINT NOT NULL,original_name VARCHAR(255) NOT NULL,mime_type VARCHAR(100) NOT NULL,size_bytes BIGINT NOT NULL,storage_key VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS related_complaints (id CHAR(36) PRIMARY KEY,complaint_id BIGINT NOT NULL,related_complaint_id BIGINT NOT NULL,match_score DECIMAL(5,4),explanation_json JSON,status VARCHAR(30) DEFAULT 'suggested',approved_by VARCHAR(64),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_related(complaint_id,related_complaint_id),FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE,FOREIGN KEY(related_complaint_id) REFERENCES complaints(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sla_policies (id INT AUTO_INCREMENT PRIMARY KEY,category VARCHAR(80) NOT NULL,bureau VARCHAR(100) NOT NULL DEFAULT '',hours INT NOT NULL,active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_sla_policy(category,bureau)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sla_events (id CHAR(36) PRIMARY KEY,complaint_id BIGINT NOT NULL,event_type VARCHAR(40) NOT NULL,details_json JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id CHAR(36) PRIMARY KEY,complaint_id BIGINT NOT NULL,kind VARCHAR(40) NOT NULL,message VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_notice_dedupe(complaint_id,kind,created_at),FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS agent_runs (id CHAR(36) PRIMARY KEY,complaint_id BIGINT NOT NULL,user_id VARCHAR(64),status VARCHAR(30),recommendation_json JSON,started_at DATETIME,completed_at DATETIME,FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS agent_tool_executions (id BIGINT AUTO_INCREMENT PRIMARY KEY,run_id CHAR(36) NOT NULL,tool_name VARCHAR(100),status VARCHAR(30),result_json JSON,error_text TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(run_id) REFERENCES agent_runs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ai_recommendations (id CHAR(36) PRIMARY KEY,run_id CHAR(36) NOT NULL,complaint_id BIGINT NOT NULL,recommendation_json JSON,confidence DECIMAL(4,3),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(run_id) REFERENCES agent_runs(id) ON DELETE CASCADE,FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS escalation_proposals (id CHAR(36) PRIMARY KEY,complaint_id BIGINT NOT NULL,reason TEXT NOT NULL,status VARCHAR(30) DEFAULT 'pending',created_by VARCHAR(64),reviewed_by VARCHAR(64),reviewed_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id CHAR(36) PRIMARY KEY,user_id VARCHAR(64),action VARCHAR(120) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id VARCHAR(100),details_json JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_audit_created(created_at),INDEX idx_audit_entity(entity_type,entity_id)) ENGINE=InnoDB;
INSERT IGNORE INTO roles(name,permissions_json) VALUES ('admin',JSON_ARRAY('all')),('officer',JSON_ARRAY('case.read','case.update','agent.run')),('viewer',JSON_ARRAY('case.read'));
INSERT IGNORE INTO bureaus(name) VALUES ('Approval Bureau'),('Administration Bureau'),('Academic Bureau'),('Finance Bureau'),('Grievance Cell');
